// Generated by esquadro: do not edit. A resource's queue (queue in
// src/resources/<resource>.tsx): the records of a filter as cards, one in
// focus, worked with the keys of the actions. A record an action takes out
// of the filter leaves, and the next takes its place.
import { useQuery } from "@tanstack/react-query"
import { Link, useNavigate } from "@tanstack/react-router"
import { Inbox } from "../icons.gen.ts"
import { useEffect, useRef, useState } from "react"
import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"
import { api } from "../api.ts"
import { actionKeys, allowed, useActions } from "./actions.tsx"
import { t, titleText } from "./i18n.ts"
import type { Rec } from "./meta.ts"
import { Picture } from "./picture.tsx"
import type { Resource } from "./resource.ts"
import { FieldValue } from "./show.tsx"
import { ErrorState, StateView, TableSkeleton } from "./states.tsx"
import { useKeys } from "./keys.tsx"

/** How many records the queue shows at a time. */
const QUEUE_SIZE = 50

/** The queue's records: the first of its filter, in the list's order. */
export function useQueue(resource: Resource) {
  const { meta, queue } = resource
  const paged = meta.pagination.includes("page")
  return useQuery({
    queryKey: [meta.name, "queue", queue?.filter],
    queryFn: ({ signal }) =>
      meta.api(api as never).list({ ...queue?.filter, ...(paged ? { page: 1, per_page: QUEUE_SIZE } : { limit: QUEUE_SIZE }) }, { signal }),
    enabled: Boolean(queue),
  })
}

/**
 * The record in focus after the list changed: the same one when it is still
 * there; else the one now where it was, or the last.
 */
export function focusAfter(items: Rec[], id: string | null, at: number): number {
  if (items.length === 0) return -1
  const same = id === null ? -1 : items.findIndex((r) => r.id === id)
  if (same >= 0) return same
  return Math.min(Math.max(at, 0), items.length - 1)
}

export function QueueView({ resource }: { resource: Resource }) {
  const { meta } = resource
  const card = resource.queue?.card ?? {}
  const list = useQueue(resource)
  const items = list.data?.items ?? []
  const [focus, setFocus] = useState<{ id: string | null; at: number }>({ id: null, at: 0 })
  const at = focusAfter(items, focus.id, focus.at)
  const current = at >= 0 ? items[at] : undefined
  const { perform, dialog } = useActions(resource)
  const navigate = useNavigate()
  const cards = useRef<HTMLDivElement>(null)

  const move = (to: number) => {
    const i = Math.min(Math.max(to, 0), items.length - 1)
    if (items[i]) setFocus({ id: items[i].id, at: i })
  }
  const run = async (r: Rec, i: number, key: string) => {
    const a = actionKeys(resource).get(key)
    if (!a) return
    // Where it was: if the action takes it out, the next comes there.
    setFocus({ id: r.id, at: i })
    if (await perform(a, r)) setFocus({ id: null, at: i })
  }
  useKeys({
    j: () => move(at + 1),
    ArrowDown: () => move(at + 1),
    k: () => move(at - 1),
    ArrowUp: () => move(at - 1),
    Enter: () => current && navigate({ to: `/${meta.name}/${current.id}` as never }),
    ...Object.fromEntries([...actionKeys(resource).keys()].map((key) => [key, () => current && run(current, at, key)])),
  })
  // The card in focus in view.
  useEffect(() => {
    cards.current?.querySelector('[data-focus="true"]')?.scrollIntoView({ block: "nearest", behavior: "smooth" })
  }, [at, current?.id])

  if (list.isPending) return <TableSkeleton columns={3} />
  if (list.isError) return <ErrorState framed error={list.error} onRetry={() => list.refetch()} />
  const total = list.data.total ?? items.length
  if (items.length === 0) {
    return <StateView framed icon={<Inbox />} title={t("queueEmpty")} description={t("queueEmptyHint")} />
  }
  return (
    <div className="flex flex-col gap-3">
      <p className="text-sm text-muted-foreground tabular-nums">{t("queueCount", { count: total })}</p>
      <div ref={cards} className="flex flex-col gap-3">
        {items.map((r, i) => {
          const focused = i === at
          const image = card.image ? (r[card.image.name] as string | null | undefined) : undefined
          const title = card.title ? titleText(card.title, r[card.title.name]) : resource.title ? titleText(resource.title, r[resource.title.name]) || meta.singular : meta.singular
          return (
            <div
              key={r.id}
              data-focus={focused}
              onClick={() => setFocus({ id: r.id, at: i })}
              className={cn(
                "flex gap-4 rounded-xl border border-border bg-card p-4 transition-shadow",
                focused ? "ring-2 ring-primary shadow-sm" : "opacity-80 hover:opacity-100",
              )}
            >
              {card.image && <Picture src={image} name={title} size="lg" className="size-24" />}
              <div className="flex min-w-0 flex-1 flex-col gap-2">
                <Link to={`/${meta.name}/${r.id}` as never} className="truncate text-base font-semibold hover:underline">
                  {title || "—"}
                </Link>
                {card.fields && card.fields.length > 0 && (
                  <dl className="flex flex-wrap gap-x-6 gap-y-1 text-sm">
                    {card.fields.map((f) => (
                      <div key={f.name} className="flex min-w-0 flex-col">
                        <dt className="text-xs text-muted-foreground">{f.label}</dt>
                        <dd className="min-w-0 truncate font-medium">
                          <FieldValue field={f} record={r} inline />
                        </dd>
                      </div>
                    ))}
                  </dl>
                )}
                <div className="mt-1 flex flex-wrap gap-2">
                  {(resource.actions ?? [])
                    .filter((a) => allowed(a, r, meta))
                    .map((a) => (
                      <Button
                        key={a.label}
                        size="sm"
                        variant={a.destructive ? "destructive-outline" : "outline"}
                        onClick={(e) => {
                          e.stopPropagation()
                          setFocus({ id: r.id, at: i })
                          perform(a, r).then((ok) => ok && setFocus({ id: null, at: i }))
                        }}
                      >
                        {a.icon && <a.icon />} {a.label}
                        {a.key && <kbd className="rounded border border-border px-1 text-[10px] text-muted-foreground">{a.key}</kbd>}
                      </Button>
                    ))}
                </div>
              </div>
            </div>
          )
        })}
      </div>
      {dialog}
    </div>
  )
}
